  'hotel' => ['label'=>'Hotel-Rezeption','icon'=>'🏨','group'=>'Gastgewerbe','from_demo'=>'agent-hotel','tools'=>['hotel','callback'],'sector_sys'=>'hotel','rules_from'=>'agent-hotel',
    'script'=>[['sys','Eingehender Anruf · +49 89 …'],
      ['a','Herzlich willkommen im Hotel Alster Residenz, hier ist Sophie von der digitalen Rezeption. Möchten Sie ein Zimmer buchen, oder darf ich Ihnen während Ihres Aufenthalts etwas Gutes tun?'],
