  'hausverwaltung' => ['label'=>'Hausverwaltung','icon'=>'🏢','group'=>'Immobilien','from_demo'=>'agent-hausverwaltung','tools'=>['callback'],'sector_sys'=>'hausverwaltung','rules_from'=>'',
    'chips'=>['Bei mir kommt Wasser aus der Decke!','Meine Nebenkostenabrechnung hat 420 € Nachzahlung – warum?','Wann ist die nächste Eigentümerversammlung?','Darf ich meinen Balkon verglasen?'],
    'script'=>[['sys','Eingehender Anruf · +49 228 … · Sonntag 22:16'],
      ['a','Rheinland Hausverwaltung, guten Tag, Sie sprechen mit Tobias, dem digitalen Service-Assistenten. Möchten Sie einen Schaden melden, oder geht es um die Abrechnung oder das Haus?'],
      ['u','Hallo, bei mir kommt Wasser aus der Decke im Bad, das wird immer mehr!'],
      ['a','Das ist ein Notfall – ich helfe Ihnen sofort. Schalten Sie bitte den Strom im Bad ab und stellen Sie Eimer unter. Rufen Sie gleich unseren Notdienst an, der ist rund um die Uhr da: 0228 99 88 77.'],
      ['u','Okay … 0228 99 88 77?'],
      ['a','Genau, 0228 99 88 77. Damit ich parallel ein Ticket anlege: Wie lautet Ihre Adresse und welche Wohnung?'],
      ['u','Beethovenstraße 12, zweiter Stock links, Familie Yilmaz.'],
      ['a','Danke, Frau Yilmaz – Beethovenstraße 12, zweiter Stock links. Klingeln Sie bitte auch bei den Nachbarn über Ihnen, vielleicht läuft dort etwas aus. Soll Sie morgen früh jemand aus der Verwaltung zurückrufen?'],
      ['u','Ja, bitte.'],
      ['sys','⚙ request callback ✓ · Wasserschaden Beethovenstraße 12 · dringend · morgen 9:00'],
      ['a','Ist eingetragen, als dringend. Jetzt aber zuerst den Notdienst anrufen – die Kollegen kommen auch nachts. Alles Gute!'],
      ['sys','Gespräch beendet · 1:18 · Notdienst-Nummer genannt ✓ · Ticket angelegt']]],
  'immobilien' => ['label'=>'Immobilienmakler','icon'=>'🏠','group'=>'Immobilien','from_demo'=>'immo-agent','tools'=>['callback'],'sector_sys'=>'immobilien','rules_from'=>'immo-agent',
    'script'=>[['sys','Eingehender Anruf · +49 176 …'],
      ['a','Lindqvist Immobilien, guten Tag – hier ist Clara, die digitale Assistentin von Frau Lindqvist. Zu welchem Objekt haben Sie eine Frage, oder suchen Sie etwas Bestimmtes?'],
      ['u','Hallo, ich rufe wegen der Wohnung in Sülz an, LQ-2041. Ist die noch frei?'],
      ['a','Ja, die ist noch verfügbar: drei Zimmer, 78 Quadratmeter mit Südbalkon, 1.290 Euro kalt plus 260 Euro Nebenkosten, frei ab dem 1. Januar. Suchen Sie für sich allein oder für mehrere Personen?'],
      ['u','Für meinen Partner und mich, wir sind beide berufstätig.'],
      ['a','Schön. Und der Einzug zum 1. Januar würde bei Ihnen passen?'],
      ['u','Ja, perfekt. Kann man sie sich anschauen?'],
      ['a','Sehr gern. Frau Lindqvist stimmt die Besichtigung persönlich mit Ihnen ab – darf sie Sie heute um 16 Uhr zurückrufen? Dann bräuchte ich noch Ihren Namen.'],
      ['u','16 Uhr passt. Sarah Klein.'],
      ['sys','⚙ request callback ✓ · Besichtigung LQ-2041 · heute 16:00'],
      ['a','Danke, Frau Klein, der Rückruf heute um 16 Uhr ist eingetragen. Für die Besichtigung halten Sie bitte Schufa-Auskunft und die letzten drei Gehaltsnachweise bereit. Bis später!'],
      ['sys','Gespräch beendet · 1:09 · Lead-Zusammenfassung an Frau Lindqvist ✓']]],
