/**
 * Demo-Konfiguration für einen Agenten (Fallback: Muster-Firma). $raw = eigene Rohdaten (z. B. eine Branche des Telefon-Agenten) statt CH_DEMO[$plan].
 * Liefert immer persona, style, voice{preset,gender,rate,pitch,role,instructions}, fillers[], chips[], script[[role,text]], du.
 */
function ch_demo_cfg(string $plan, ?array $raw=null): array {
  $d = $raw ?? (CH_DEMO[$plan] ?? ['company'=>'Muster GmbH','tone'=>'freundlich-professionell','lang'=>'de','persona'=>'Alex','du'=>true,'voice'=>['preset'=>'m_freundlich'],
    'greeting'=>'Hallo, hier ist Alex, der Demo-Agent der Muster GmbH. Was kann ich für dich tun?','chips'=>['Was kannst du?','Wie funktioniert die Einrichtung?'],
    'kb'=>"Muster GmbH, Musterstraße 1, 10115 Berlin. Öffnungszeiten Mo–Fr 9–17 Uhr. Kontakt: info@muster.de. Leistungen: Beratung, Service, Support.",
    'script'=>[['a','Hallo, hier ist Alex, der Demo-Agent der Muster GmbH. Was kann ich für dich tun?'],['u','Wann habt ihr geöffnet?'],['a','Montag bis Freitag von 9 bis 17 Uhr – soll ich dir noch etwas zu unseren Leistungen sagen?']]]);
  /* Stimme: Voreinstellung (speech-lib ch_tts_voices) + Persona-Feinschliff; Geschlecht folgt der Voreinstellung */
  $v = is_array($d['voice'] ?? null) ? $d['voice'] : [];
  $pid = (string)($v['preset'] ?? '');
  if(preg_match('/^([fm])_[a-z0-9_]{2,30}$/', $pid, $pm)) $g = $pm[1];
  else { $g = ($v['gender'] ?? 'f') === 'm' ? 'm' : 'f'; $pid = $g === 'm' ? 'm_freundlich' : 'f_warm'; }
  $num = fn($x, float $def): float => is_numeric($x) ? (float)$x : $def;
  $d['voice'] = ['preset'=>$pid, 'gender'=>$g,
    'rate'=>round(max(0.85, min(1.15, $num($v['rate'] ?? null, 1.0))), 2), 'pitch'=>round(max(0.8, min(1.2, $num($v['pitch'] ?? null, 1.0))), 2),
    'role'=>trim((string)($v['role'] ?? '')), 'instructions'=>trim((string)($v['instructions'] ?? ''))];
  $d['fillers'] = array_values(array_filter(array_map('strval', (array)($d['fillers'] ?? [])), fn($f)=>trim($f)!=='')) ?: ['Einen Moment bitte, ich schaue kurz nach.','Augenblick, ich prüfe das gerade.'];
  $d['chips'] = array_values(array_filter(array_map('strval', (array)($d['chips'] ?? [])), fn($c)=>trim($c)!==''));
  $d += ['persona'=>'','du'=>false,'greeting'=>'','company'=>'','kb'=>'','tone'=>'freundlich-professionell','lang'=>'de',
    'style'=>'Freundlich, klar und natürlich – wie eine erfahrene Mitarbeiterin oder ein erfahrener Mitarbeiter genau dieses Betriebs. Kurze Sätze, eine Frage pro Antwort, wichtige Angaben wiederholen und bestätigen lassen. Bei Ärger zuerst Verständnis zeigen, dann eine konkrete Lösung anbieten; bei Notfällen sofort auf 112 bzw. den Notdienst verweisen. Keine Floskeln, nichts erfinden.'];
  /* Beispielgespräch (Autoplay): [[role,text],…] mit role a|u|sys; [step,role,text] wird ebenfalls akzeptiert */
  $sc = [];
  foreach((array)($d['script'] ?? []) as $row){
    if(!is_array($row) || count($row) < 2) continue; $row = array_values($row); $n = count($row);
    $r = (string)$row[$n-2]; $t = trim((string)$row[$n-1]);
    if(in_array($r, ['a','u','sys'], true) && $t !== '') $sc[] = [$r, $t];
  }
  $d['script'] = $sc ?: ($d['greeting'] !== '' ? [['a', (string)$d['greeting']]] : []);
  return $d + ['widget_key'=>null,'widget_domain'=>'','widget_on'=>0];
}
/** Branche des Telefon-Agenten → Konfiguration wie ch_demo_cfg + sector, label, icon, group, tools[], sector_sys, rules_from, services[], address. Unbekannt → zahnarzt. */
function ch_phone_sector_cfg(string $key=''): array {
  $k = isset(CH_PHONE_SECTORS[$key]) ? $key : 'zahnarzt';
  $s = CH_PHONE_SECTORS[$k];
  $base = (isset($s['from_demo']) && isset(CH_DEMO[$s['from_demo']])) ? CH_DEMO[$s['from_demo']] : [];
  $raw = array_merge($base, $s);
  if(isset($base['voice'], $s['voice']) && is_array($base['voice']) && is_array($s['voice'])) $raw['voice'] = array_merge($base['voice'], $s['voice']);
  unset($raw['from_demo']);
  $d = ch_demo_cfg('agent-phone', $raw);
  $d['sector'] = $k;
  $d += ['label'=>$k,'icon'=>'☎','group'=>'Service','tools'=>['callback'],'sector_sys'=>'service','rules_from'=>'','services'=>[],'address'=>''];
  $d['tools'] = array_values(array_filter((array)$d['tools'], 'is_string'));
  $d['services'] = array_values(array_filter((array)$d['services'], fn($x)=>is_array($x) && trim((string)($x['name'] ?? ''))!=='' && (int)($x['duration_min'] ?? 0)>0));
  return $d;
}
